select
d.id,d.item_code,d.item_name,d.specification,d.num_measure_id,d.num_measure_name,d.weight_measure_id,d.weight_measure_name,d.item_type_id,d.item_type_code,d.item_type_name,d.workstage_id,d.workstage_name,d.if_enable,d.if_safe_stock,d.min_stock,d.max_stock,d.remark,d.version,d.is_deleted,d.attr1,d.attr2,d.attr3,d.create_by,d.create_time,d.update_by,d.update_time
from md_item d

	is_deleted = 0

		and id = #{id}


		and item_code = #{itemCode}


		and item_name = #{itemName}


		and specification = #{specification}


		and num_measure_id = #{numMeasureId}


		and num_measure_name = #{numMeasureName}


		and weight_measure_id = #{weightMeasureId}


		and weight_measure_name = #{weightMeasureName}


		and item_type_id = #{itemTypeId}


		and item_type_code = #{itemTypeCode}


		and item_type_name = #{itemTypeName}


		and workstage_id = #{workstageId}


		and workstage_name = #{workstageName}


		and if_enable = #{ifEnable}


		and if_safe_stock = #{ifSafeStock}


		and min_stock = #{minStock}


		and max_stock = #{maxStock}


		and remark = #{remark}


		and version = #{version}


		and is_deleted = #{isDeleted}


		and attr1 = #{attr1}


		and attr2 = #{attr2}


		and attr3 = #{attr3}


		and create_by = #{createBy}


		and create_time = #{createTime}


		and update_by = #{updateBy}


		and update_time = #{updateTime}


order by specification asc

select count(1)
from md_item

	is_deleted = 0

		and id = #{id}


